/**
 * Picture-subtitle OCR fixtures (committed under fixtures/subtitle-ocr/,
 * regenerated by scripts/generate-subtitle-ocr-fixtures.ts) and the facts the
 * tests assert about them.
 */
import { existsSync } from "node:fs";
import { homedir } from "node:os";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

export const SUBTITLE_OCR_FIXTURE_DIR = resolve(fileURLToPath(new URL("../../fixtures/subtitle-ocr", import.meta.url)));
export const subtitleOcrFixture = (name: string): string => join(SUBTITLE_OCR_FIXTURE_DIR, name);

/** Synthetic cues rendered (DejaVu Sans Bold, white on a black outline) into ocr-synthetic.sup. */
export const SYNTHETIC_CUES = [
  { startMs: 1000, endMs: 3000, text: "Hello from SpaceFleet" },
  { startMs: 4000, endMs: 6500, text: "Picture subtitles\nare read by OCR" },
  { startMs: 8000, endMs: 10_000, text: "The quick brown fox" },
] as const;

/**
 * DVD-style VobSub samples (1920x1080 canvas, pictures from ~47.9 s, multi-line
 * cues, French accents), generated like ocr-synthetic-dvdsub.mkv but rendered in
 * Liberation Sans Bold: startMs/endMs/text are the authored cues the generator
 * renders; start/end are what the decoder reports — start = the generated cue
 * start, end = start + the dvdsub SPU stop delay, which the encoder truncates
 * to whole 1024/90 ms ticks (so end lands up to ~11 ms before endMs).
 */
export const VOBSUB_SAMPLES = {
  eng: {
    file: "vobsub-sample-eng.mkv",
    language: "eng",
    tesseractLang: "eng",
    cues: [
      { startMs: 47_913, endMs: 49_751, start: "00:00:47,913", end: "00:00:49,745", text: "[GULLS CALLING]" },
      { startMs: 50_187, endMs: 52_904, start: "00:00:50,187", end: "00:00:52,895", text: "The ferry left an hour ago.\nWe will have to row across." },
      { startMs: 53_142, endMs: 55_268, start: "00:00:53,142", end: "00:00:55,258", text: "Row? In this weather?\nYou cannot be serious." },
      { startMs: 55_629, endMs: 57_806, start: "00:00:55,629", end: "00:00:57,802", text: "Pack the lantern\nand the spare oars." },
    ],
  },
  fre: {
    file: "vobsub-sample-fre.mkv",
    language: "fre",
    tesseractLang: "fra",
    cues: [
      { startMs: 49_734, endMs: 52_712, start: "00:00:49,734", end: "00:00:52,704", text: "Le bac est déjà parti.\nIl faudra traverser à la rame." },
      { startMs: 52_956, endMs: 55_071, start: "00:00:52,956", end: "00:00:55,061", text: "Ça alors, avec ce vent ?" },
      { startMs: 55_318, endMs: 57_563, start: "00:00:55,318", end: "00:00:57,559", text: "Prends la lanterne\net les rames de secours." },
    ],
  },
} as const;

/**
 * Language data for OCR tests: never downloaded by the tests. Populate once with
 * `bun packages/ingest-core/scripts/generate-subtitle-ocr-fixtures.ts --lang-data`
 * (or point SF_SUBTITLE_OCR_TEST_LANG_DIR at a dir holding eng/fra .traineddata.gz).
 */
export const SUBTITLE_OCR_TEST_LANG_DIR =
  process.env.SF_SUBTITLE_OCR_TEST_LANG_DIR ?? join(homedir(), ".cache", "sf-subtitle-ocr-tessdata");

export const testLangDataAvailable = (codes: string[]): boolean =>
  codes.every((code) => existsSync(join(SUBTITLE_OCR_TEST_LANG_DIR, `${code}.traineddata.gz`)));
